-- State transitions declared for Mail (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION messaging.mails_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."state" IS DISTINCT FROM OLD."state" AND NOT (
           (COALESCE(OLD."state"::text, ''), COALESCE(NEW."state"::text, '')) IN (('exception', 'cancel'), ('exception', 'outgoing'), ('outgoing', 'cancel'), ('outgoing', 'exception'), ('outgoing', 'sent'), ('sent', 'received'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: mails.state % -> %', OLD."state", NEW."state";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS mails_state_transition_check ON messaging.mails;
CREATE TRIGGER mails_state_transition_check
    BEFORE UPDATE OF "state" ON messaging.mails
    FOR EACH ROW EXECUTE FUNCTION messaging.mails_state_transition_check();
